#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import decodeAudio from 'audio-decode';

const HERE = path.dirname(new URL(import.meta.url).pathname);

function printUsage() {
  console.log(`Usage:
  node tools/pitch-offline-bench/benchmark.mjs --manifest <path> --wav <take1.wav> --wav <take2.wav> [--wav <take3.wav>] [options]

Options:
  --manifest <path>   Session manifest JSON generated by generate-manifest.mjs
  --wav <path>        WAV file path (repeat --wav for multiple takes)
  --config <path>     Benchmark config JSON (default: benchmark-config.default.json)
  --out <path>        Output JSON path (default: output/offline-benchmark-results.json)
  --help              Show this help
`);
}

function parseArgs(argv) {
  const args = {
    manifest: null,
    wavs: [],
    config: path.join(HERE, 'benchmark-config.default.json'),
    out: path.join(HERE, 'output', 'offline-benchmark-results.json')
  };

  for (let i = 0; i < argv.length; i += 1) {
    const key = argv[i];
    const val = argv[i + 1];
    if (key === '--help') {
      printUsage();
      process.exit(0);
    }
    if (key === '--manifest' && val) {
      args.manifest = path.resolve(val);
      i += 1;
      continue;
    }
    if (key === '--wav' && val) {
      args.wavs.push(path.resolve(val));
      i += 1;
      continue;
    }
    if (key === '--config' && val) {
      args.config = path.resolve(val);
      i += 1;
      continue;
    }
    if (key === '--out' && val) {
      args.out = path.resolve(val);
      i += 1;
      continue;
    }
    throw new Error(`Unknown or incomplete argument: ${key}`);
  }

  if (!args.manifest) {
    throw new Error('--manifest is required');
  }
  if (args.wavs.length === 0) {
    throw new Error('At least one --wav file is required');
  }
  return args;
}

function clamp01(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

function mean(values) {
  if (!values.length) return 0;
  let sum = 0;
  for (const value of values) {
    sum += value;
  }
  return sum / values.length;
}

function median(values) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[middle - 1] + sorted[middle]) / 2;
  }
  return sorted[middle];
}

function stdDev(values) {
  if (values.length < 2) return null;
  const avg = mean(values);
  let variance = 0;
  for (const value of values) {
    const delta = value - avg;
    variance += delta * delta;
  }
  return Math.sqrt(variance / values.length);
}

function computeRms(samples) {
  if (!samples.length) return 0;
  let sumSquares = 0;
  for (let i = 0; i < samples.length; i += 1) {
    const value = samples[i];
    sumSquares += value * value;
  }
  return Math.sqrt(sumSquares / samples.length);
}

function getRelativeDiff(a, b) {
  const denom = Math.max(Math.abs(b), 1e-6);
  return Math.abs(a - b) / denom;
}

function pushHistory(history, value) {
  history.shift();
  history.push(value);
}

function parabolaInterp(n, yLeft, yCenter, yRight) {
  const nom = -4 * n * yCenter + (2 * n - 1) * yRight + (2 * n + 1) * yLeft;
  const denom = 2 * (yLeft - 2 * yCenter + yRight);
  if (!Number.isFinite(denom) || Math.abs(denom) < 1e-12) {
    return n;
  }
  const estimate = nom / denom;
  if (!Number.isFinite(estimate) || estimate < n - 1 || estimate > n + 1) {
    return n;
  }
  return estimate;
}

function detectPitchYin(samples, sampleRate, minFreq, maxFreq, threshold, scratch) {
  const tauMin = Math.max(2, Math.floor(sampleRate / Math.max(1, maxFreq)));
  const tauMax = Math.floor(sampleRate / Math.max(1, minFreq));
  const safeTauMax = Math.min(tauMax, samples.length - 1);
  if (safeTauMax <= tauMin + 2) {
    return { frequencyHz: -1, cmnd: 1 };
  }

  scratch.fill(0, tauMin, safeTauMax + 1);
  for (let tau = tauMin; tau < safeTauMax; tau += 1) {
    let sum = 0;
    for (let j = 0; j < samples.length - tau; j += 1) {
      const diff = samples[j] - samples[j + tau];
      sum += diff * diff;
    }
    scratch[tau] = sum;
  }

  let acc = 0;
  for (let tau = tauMin; tau < safeTauMax; tau += 1) {
    acc += scratch[tau];
    if (acc <= 1e-12) {
      scratch[tau] = 1;
      continue;
    }
    scratch[tau] = (scratch[tau] * (tau + 1 - tauMin)) / acc;
  }

  let minTau = -1;
  let minCmnd = 1;
  for (let tau = tauMin + 1; tau < safeTauMax - 1; tau += 1) {
    if (scratch[tau] < threshold && scratch[tau] < scratch[tau + 1]) {
      minTau = parabolaInterp(tau, scratch[tau - 1], scratch[tau], scratch[tau + 1]);
      minCmnd = scratch[tau];
      break;
    }
  }

  if (!Number.isFinite(minTau) || minTau <= 0) {
    return { frequencyHz: -1, cmnd: 1 };
  }

  return {
    frequencyHz: sampleRate / minTau,
    cmnd: clamp01(minCmnd)
  };
}

function detectPitchAutocorr(samples, sampleRate, minFreq, maxFreq, energyThreshold, correlationThreshold) {
  let meanValue = 0;
  for (let i = 0; i < samples.length; i += 1) {
    meanValue += samples[i];
  }
  meanValue /= samples.length;

  let energy = 0;
  for (let i = 0; i < samples.length; i += 1) {
    const centered = samples[i] - meanValue;
    energy += centered * centered;
  }
  const rms = Math.sqrt(energy / samples.length);
  if (!Number.isFinite(rms) || rms < energyThreshold) {
    return { frequencyHz: -1, confidence: 0 };
  }

  const minLag = Math.max(1, Math.floor(sampleRate / Math.max(1, maxFreq)));
  const maxLag = Math.max(minLag + 1, Math.floor(sampleRate / Math.max(1, minFreq)));
  const safeMaxLag = Math.min(maxLag, samples.length - 2);

  let bestLag = -1;
  let bestCorrelation = -1;
  for (let lag = minLag; lag <= safeMaxLag; lag += 1) {
    let cross = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < samples.length - lag; i += 1) {
      const a = samples[i] - meanValue;
      const b = samples[i + lag] - meanValue;
      cross += a * b;
      normA += a * a;
      normB += b * b;
    }
    const denom = Math.sqrt(normA * normB);
    if (denom <= 1e-8) continue;
    const corr = cross / denom;
    if (corr > bestCorrelation) {
      bestCorrelation = corr;
      bestLag = lag;
    }
  }

  if (bestLag <= 0 || bestCorrelation < correlationThreshold) {
    return {
      frequencyHz: -1,
      confidence: clamp01((bestCorrelation - 0.3) / Math.max(0.01, correlationThreshold - 0.3))
    };
  }

  const confidence = clamp01((bestCorrelation - correlationThreshold) / Math.max(0.01, 1 - correlationThreshold));
  return { frequencyHz: sampleRate / bestLag, confidence };
}

function detectPitchCustomWorklet(
  samples,
  sampleRate,
  minFreq,
  maxFreq,
  energyThreshold,
  correlationThreshold,
  options = {}
) {
  const effectiveEnergyThreshold = Number.isFinite(options.energy_threshold)
    ? Math.max(0, options.energy_threshold)
    : energyThreshold;
  const effectiveCorrelationThreshold = Number.isFinite(options.correlation_threshold)
    ? clamp01(options.correlation_threshold)
    : correlationThreshold;

  let meanValue = 0;
  for (let i = 0; i < samples.length; i += 1) {
    meanValue += samples[i];
  }
  meanValue /= samples.length;

  let energy = 0;
  for (let i = 0; i < samples.length; i += 1) {
    const centered = samples[i] - meanValue;
    energy += centered * centered;
  }
  const rms = Math.sqrt(energy / samples.length);
  if (!Number.isFinite(rms) || rms < effectiveEnergyThreshold) {
    return { frequencyHz: -1, confidence: 0 };
  }

  const minLag = Math.max(1, Math.floor(sampleRate / Math.max(1, maxFreq)));
  const maxLag = Math.max(minLag + 1, Math.floor(sampleRate / Math.max(1, minFreq)));
  const safeMaxLag = Math.min(maxLag, samples.length - 2);

  let bestLag = -1;
  let bestCorrelation = -1;
  for (let lag = minLag; lag <= safeMaxLag; lag += 1) {
    let cross = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < samples.length - lag; i += 1) {
      const a = samples[i] - meanValue;
      const b = samples[i + lag] - meanValue;
      cross += a * b;
      normA += a * a;
      normB += b * b;
    }
    const denom = Math.sqrt(normA * normB);
    if (denom <= 1e-8) continue;
    const corr = cross / denom;
    if (corr > bestCorrelation) {
      bestCorrelation = corr;
      bestLag = lag;
    }
  }

  if (bestLag <= 0 || bestCorrelation < effectiveCorrelationThreshold) {
    return { frequencyHz: -1, confidence: clamp01(bestCorrelation) };
  }

  const confidence = clamp01((bestCorrelation - 0.45) / 0.5);
  return { frequencyHz: sampleRate / bestLag, confidence };
}

function resampleLinear(input, inRate, outRate) {
  if (inRate === outRate) {
    return input;
  }
  const ratio = outRate / inRate;
  const outLength = Math.max(1, Math.floor(input.length * ratio));
  const output = new Float32Array(outLength);
  for (let i = 0; i < outLength; i += 1) {
    const position = i / ratio;
    const index0 = Math.floor(position);
    const index1 = Math.min(input.length - 1, index0 + 1);
    const frac = position - index0;
    output[i] = input[index0] * (1 - frac) + input[index1] * frac;
  }
  return output;
}

function runTuneoDetector(samples, sampleRate, params) {
  const windowSeconds = Number.isFinite(params.window_seconds) ? params.window_seconds : 0.2040816327;
  const chunkSeconds = Number.isFinite(params.chunk_seconds) ? params.chunk_seconds : 1 / 15;
  const minFreqHz = Number.isFinite(params.min_freq_hz) ? params.min_freq_hz : 30;
  const maxFreqHz = Number.isFinite(params.max_freq_hz) ? params.max_freq_hz : 500;
  const thresholdDefault = Number.isFinite(params.threshold_default) ? params.threshold_default : 0.15;
  const thresholdNoisy = Number.isFinite(params.threshold_noisy) ? params.threshold_noisy : 0.6;
  const maxPitchDev = Number.isFinite(params.max_pitch_dev) ? params.max_pitch_dev : 0.2;
  const rmsGap = Number.isFinite(params.rms_gap) ? params.rms_gap : 1.1;
  const adaptive = params.adaptive !== false;
  const minRms = Number.isFinite(params.min_rms) ? params.min_rms : 0.0008;

  const windowSize = Math.max(128, Math.floor(windowSeconds * sampleRate));
  const chunkSize = Math.max(16, Math.floor(chunkSeconds * sampleRate));
  const historySize = 3;
  const pitchHistory = new Array(historySize).fill(-1);
  const rmsHistory = new Array(historySize).fill(0);
  const rolling = new Float32Array(windowSize);
  const scratch = new Float32Array(windowSize);
  let hasFilled = false;
  let previousMidi = null;
  const frames = [];

  for (let end = chunkSize; end <= samples.length; end += chunkSize) {
    const start = end - chunkSize;
    const chunk = samples.subarray(start, end);
    if (chunkSize >= windowSize) {
      rolling.set(chunk.subarray(chunk.length - windowSize));
      hasFilled = true;
    } else {
      rolling.copyWithin(0, chunkSize);
      rolling.set(chunk, windowSize - chunkSize);
      if (end >= windowSize) {
        hasFilled = true;
      }
    }
    if (!hasFilled) continue;

    const rms = computeRms(chunk);
    pushHistory(rmsHistory, rms);

    let minFreq = minFreqHz;
    let maxFreq = maxFreqHz;
    let threshold = thresholdDefault;

    const previousPitch = pitchHistory[historySize - 1];
    const secondPreviousPitch = pitchHistory[historySize - 2];
    const previousRms = rmsHistory[historySize - 1];
    const secondPreviousRms = rmsHistory[historySize - 2];
    let restrictRange = adaptive;
    restrictRange = restrictRange && previousPitch > 0;
    restrictRange = restrictRange && previousRms < secondPreviousRms * rmsGap;
    restrictRange = restrictRange && getRelativeDiff(previousPitch, secondPreviousPitch) <= maxPitchDev;
    if (restrictRange) {
      minFreq = previousPitch * (1 - maxPitchDev);
      maxFreq = previousPitch * (1 + maxPitchDev);
      threshold = thresholdNoisy;
    }

    const tSeconds = end / sampleRate;
    if (!Number.isFinite(rms) || rms < minRms) {
      pushHistory(pitchHistory, -1);
      previousMidi = null;
      frames.push({ t_seconds: tSeconds, midi_estimate: null, confidence: 0 });
      continue;
    }

    const yinResult = detectPitchYin(rolling, sampleRate, minFreq, maxFreq, threshold, scratch);
    if (yinResult.frequencyHz <= 0) {
      pushHistory(pitchHistory, -1);
      previousMidi = null;
      frames.push({ t_seconds: tSeconds, midi_estimate: null, confidence: 0 });
      continue;
    }

    pushHistory(pitchHistory, yinResult.frequencyHz);
    const midiEstimate = 69 + 12 * Math.log2(yinResult.frequencyHz / 440);
    const yinScore = clamp01(1 - yinResult.cmnd / Math.max(1e-4, threshold));
    const energyScore = clamp01((rms - minRms) / Math.max(1e-5, minRms * 10));
    const stabilityScore =
      previousMidi === null ? 0.7 : clamp01(1 - Math.abs(midiEstimate - previousMidi) / 2.5);
    const confidence = clamp01(0.45 + 0.35 * yinScore + 0.15 * energyScore + 0.05 * stabilityScore);
    previousMidi = midiEstimate;
    frames.push({ t_seconds: tSeconds, midi_estimate: midiEstimate, confidence });
  }

  return frames;
}

function runAutocorrDetector(samples, sampleRate, params) {
  const windowSeconds = Number.isFinite(params.window_seconds) ? params.window_seconds : 0.14;
  const chunkSeconds = Number.isFinite(params.chunk_seconds) ? params.chunk_seconds : 0.04;
  const minFreqHz = Number.isFinite(params.min_freq_hz) ? params.min_freq_hz : 55;
  const maxFreqHz = Number.isFinite(params.max_freq_hz) ? params.max_freq_hz : 1200;
  const energyThreshold = Number.isFinite(params.energy_threshold) ? params.energy_threshold : 0.0025;
  const correlationThreshold = Number.isFinite(params.correlation_threshold) ? params.correlation_threshold : 0.58;

  const windowSize = Math.max(128, Math.floor(windowSeconds * sampleRate));
  const chunkSize = Math.max(16, Math.floor(chunkSeconds * sampleRate));
  const rolling = new Float32Array(windowSize);
  let hasFilled = false;
  const frames = [];

  for (let end = chunkSize; end <= samples.length; end += chunkSize) {
    const start = end - chunkSize;
    const chunk = samples.subarray(start, end);
    if (chunkSize >= windowSize) {
      rolling.set(chunk.subarray(chunk.length - windowSize));
      hasFilled = true;
    } else {
      rolling.copyWithin(0, chunkSize);
      rolling.set(chunk, windowSize - chunkSize);
      if (end >= windowSize) {
        hasFilled = true;
      }
    }
    if (!hasFilled) continue;

    const result = detectPitchAutocorr(rolling, sampleRate, minFreqHz, maxFreqHz, energyThreshold, correlationThreshold);
    const tSeconds = end / sampleRate;
    if (result.frequencyHz <= 0) {
      frames.push({ t_seconds: tSeconds, midi_estimate: null, confidence: result.confidence ?? 0 });
      continue;
    }
    const midiEstimate = 69 + 12 * Math.log2(result.frequencyHz / 440);
    frames.push({
      t_seconds: tSeconds,
      midi_estimate: midiEstimate,
      confidence: clamp01(result.confidence ?? 0)
    });
  }

  return frames;
}

function runCustomZeroRefDetector(samples, sampleRate, params) {
  const windowSeconds = Number.isFinite(params.window_seconds) ? params.window_seconds : 2048 / 44100;
  const chunkSeconds = Number.isFinite(params.chunk_seconds) ? params.chunk_seconds : 1024 / 44100;
  const minFreqHz = Number.isFinite(params.min_freq_hz) ? params.min_freq_hz : 65;
  const maxFreqHz = Number.isFinite(params.max_freq_hz) ? params.max_freq_hz : 1200;
  const energyThreshold = Number.isFinite(params.energy_threshold) ? params.energy_threshold : 0.0032;
  const correlationThreshold = Number.isFinite(params.correlation_threshold) ? params.correlation_threshold : 0.58;
  const decayGraceFrames = Number.isFinite(params.decay_grace_frames)
    ? Math.max(0, Math.floor(params.decay_grace_frames))
    : 0;
  const decayEnergyFactor = Number.isFinite(params.decay_energy_factor)
    ? Math.max(0.2, Math.min(1, params.decay_energy_factor))
    : 1;
  const decayCorrelationThreshold = Number.isFinite(params.decay_correlation_threshold)
    ? clamp01(params.decay_correlation_threshold)
    : correlationThreshold;

  const windowSize = Math.max(128, Math.floor(windowSeconds * sampleRate));
  const chunkSize = Math.max(16, Math.floor(chunkSeconds * sampleRate));
  const rolling = new Float32Array(windowSize);
  let hasFilled = false;
  let decayFramesRemaining = 0;
  const frames = [];

  for (let end = chunkSize; end <= samples.length; end += chunkSize) {
    const start = end - chunkSize;
    const chunk = samples.subarray(start, end);
    if (chunkSize >= windowSize) {
      rolling.set(chunk.subarray(chunk.length - windowSize));
      hasFilled = true;
    } else {
      rolling.copyWithin(0, chunkSize);
      rolling.set(chunk, windowSize - chunkSize);
      if (end >= windowSize) {
        hasFilled = true;
      }
    }
    if (!hasFilled) continue;

    const decayActive = decayFramesRemaining > 0;
    const result = detectPitchCustomWorklet(
      rolling,
      sampleRate,
      minFreqHz,
      maxFreqHz,
      energyThreshold,
      correlationThreshold,
      {
        energy_threshold: decayActive ? energyThreshold * decayEnergyFactor : energyThreshold,
        correlation_threshold: decayActive
          ? Math.min(correlationThreshold, decayCorrelationThreshold)
          : correlationThreshold
      }
    );
    const tSeconds = end / sampleRate;
    if (result.frequencyHz <= 0) {
      if (decayFramesRemaining > 0) {
        decayFramesRemaining -= 1;
      }
      frames.push({ t_seconds: tSeconds, midi_estimate: null, confidence: result.confidence ?? 0 });
      continue;
    }

    if (decayGraceFrames > 0) {
      decayFramesRemaining = decayGraceFrames;
    }

    const midiEstimate = 69 + 12 * Math.log2(result.frequencyHz / 440);
    frames.push({
      t_seconds: tSeconds,
      midi_estimate: midiEstimate,
      confidence: clamp01(result.confidence ?? 0)
    });
  }

  return frames;
}

function runDetector(samples, sampleRate, candidate) {
  const params = candidate.params ?? {};
  const analysisSampleRate = Number.isFinite(params.analysis_sample_rate)
    ? Math.max(2000, Math.floor(params.analysis_sample_rate))
    : sampleRate;
  const analysisSamples = analysisSampleRate === sampleRate
    ? samples
    : resampleLinear(samples, sampleRate, analysisSampleRate);

  const t0 = performance.now();
  let frames = [];
  if (candidate.algorithm === 'tuneo') {
    frames = runTuneoDetector(analysisSamples, analysisSampleRate, params);
  } else if (candidate.algorithm === 'autocorr') {
    frames = runAutocorrDetector(analysisSamples, analysisSampleRate, params);
  } else if (candidate.algorithm === 'custom_zero_ref') {
    frames = runCustomZeroRefDetector(analysisSamples, analysisSampleRate, params);
  } else {
    throw new Error(`Unsupported algorithm: ${candidate.algorithm}`);
  }
  const runtimeMs = performance.now() - t0;
  return {
    frames,
    runtimeMs,
    analysisSampleRate,
    durationSeconds: analysisSamples.length / analysisSampleRate
  };
}

function lowerBoundFrames(frames, targetTime) {
  let lo = 0;
  let hi = frames.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (frames[mid].t_seconds < targetTime) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

function computeQualityScore(detectRate, inTuneRate, medianAbsCents, jitterCents, octaveErrorRate) {
  const detectComponent = 0.42 * clamp01(detectRate);
  const tuneComponent = 0.28 * clamp01(inTuneRate);
  const medianComponent = 0.18 * (1 - clamp01((medianAbsCents ?? 120) / 120));
  const jitterComponent = 0.12 * (1 - clamp01((jitterCents ?? 140) / 140));
  const octavePenalty = 0.15 * clamp01(octaveErrorRate);
  const raw = 100 * (detectComponent + tuneComponent + medianComponent + jitterComponent - octavePenalty);
  return Math.max(0, Math.round(raw));
}

function initNoteAccumulator(event) {
  return {
    note_order: event.note_order,
    note: event.note,
    midi: event.midi,
    string: event.string,
    fret: event.fret,
    total_frames: 0,
    valid_frames: 0,
    in_tune_frames: 0,
    octave_errors: 0,
    confidence_sum: 0,
    abs_cents: [],
    signed_cents: []
  };
}

function evaluateFrames(frames, events, evalCfg) {
  const minConfidence = Number.isFinite(evalCfg.min_confidence) ? evalCfg.min_confidence : 0.25;
  const inTuneCents = Number.isFinite(evalCfg.in_tune_cents) ? evalCfg.in_tune_cents : 35;
  const octaveErrorMin = Number.isFinite(evalCfg.octave_error_min_semitones) ? evalCfg.octave_error_min_semitones : 5.5;

  let totalFrames = 0;
  let validFrames = 0;
  let inTuneFrames = 0;
  let octaveErrors = 0;
  let confidenceSum = 0;
  const absCentsAll = [];
  const signedCentsAll = [];
  const noteMap = new Map();

  for (const event of events) {
    const startIdx = lowerBoundFrames(frames, event.start_s);
    const endIdx = lowerBoundFrames(frames, event.end_s);
    const noteKey = String(event.note_order);
    if (!noteMap.has(noteKey)) {
      noteMap.set(noteKey, initNoteAccumulator(event));
    }
    const noteAcc = noteMap.get(noteKey);
    const frameCount = Math.max(0, endIdx - startIdx);
    totalFrames += frameCount;
    noteAcc.total_frames += frameCount;

    for (let i = startIdx; i < endIdx; i += 1) {
      const frame = frames[i];
      if (frame.midi_estimate === null || !Number.isFinite(frame.midi_estimate)) continue;
      if (!Number.isFinite(frame.confidence) || frame.confidence < minConfidence) continue;

      const deltaSemitones = frame.midi_estimate - event.midi;
      const deltaCents = deltaSemitones * 100;
      const absCents = Math.abs(deltaCents);

      validFrames += 1;
      noteAcc.valid_frames += 1;
      confidenceSum += frame.confidence;
      noteAcc.confidence_sum += frame.confidence;
      absCentsAll.push(absCents);
      signedCentsAll.push(deltaCents);
      noteAcc.abs_cents.push(absCents);
      noteAcc.signed_cents.push(deltaCents);

      if (absCents <= inTuneCents) {
        inTuneFrames += 1;
        noteAcc.in_tune_frames += 1;
      }
      if (Math.abs(deltaSemitones) >= octaveErrorMin) {
        octaveErrors += 1;
        noteAcc.octave_errors += 1;
      }
    }
  }

  const detectRate = totalFrames > 0 ? validFrames / totalFrames : 0;
  const inTuneRate = totalFrames > 0 ? inTuneFrames / totalFrames : 0;
  const medianAbsCents = median(absCentsAll);
  const jitterCents = stdDev(signedCentsAll);
  const octaveErrorRate = validFrames > 0 ? octaveErrors / validFrames : 0;
  const avgConfidence = validFrames > 0 ? confidenceSum / validFrames : 0;
  const qualityScore = computeQualityScore(detectRate, inTuneRate, medianAbsCents, jitterCents, octaveErrorRate);

  const noteSummaries = Array.from(noteMap.values())
    .map((noteAcc) => {
      const detect = noteAcc.total_frames > 0 ? noteAcc.valid_frames / noteAcc.total_frames : 0;
      const inTune = noteAcc.total_frames > 0 ? noteAcc.in_tune_frames / noteAcc.total_frames : 0;
      const med = median(noteAcc.abs_cents);
      const jitter = stdDev(noteAcc.signed_cents);
      const octave = noteAcc.valid_frames > 0 ? noteAcc.octave_errors / noteAcc.valid_frames : 0;
      return {
        note_order: noteAcc.note_order,
        note: noteAcc.note,
        midi: noteAcc.midi,
        string: noteAcc.string,
        fret: noteAcc.fret,
        detect_rate: detect,
        in_tune_rate: inTune,
        median_abs_cents: med,
        jitter_cents: jitter,
        octave_error_rate: octave,
        avg_confidence: noteAcc.valid_frames > 0 ? noteAcc.confidence_sum / noteAcc.valid_frames : 0
      };
    })
    .sort((a, b) => a.note_order - b.note_order);

  return {
    total_frames: totalFrames,
    valid_frames: validFrames,
    detect_rate: detectRate,
    in_tune_rate: inTuneRate,
    median_abs_cents: medianAbsCents,
    jitter_cents: jitterCents,
    octave_error_rate: octaveErrorRate,
    avg_confidence: avgConfidence,
    quality_score: qualityScore,
    note_summaries: noteSummaries
  };
}

async function decodeWavMono(filePath) {
  const encoded = await fs.readFile(filePath);
  const audio = await decodeAudio(encoded);
  const channels = audio.numberOfChannels;
  const mono = new Float32Array(audio.length);
  for (let ch = 0; ch < channels; ch += 1) {
    const data = audio.getChannelData(ch);
    for (let i = 0; i < data.length; i += 1) {
      mono[i] += data[i] / channels;
    }
  }
  return {
    samples: mono,
    sampleRate: audio.sampleRate,
    durationSeconds: mono.length / audio.sampleRate
  };
}

function formatPercent(value) {
  return `${(value * 100).toFixed(1)}%`;
}

function formatMaybeNumber(value, digits = 1) {
  return value === null || !Number.isFinite(value) ? '--' : value.toFixed(digits);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const manifestRaw = await fs.readFile(args.manifest, 'utf8');
  const configRaw = await fs.readFile(args.config, 'utf8');
  const manifest = JSON.parse(manifestRaw);
  const config = JSON.parse(configRaw);

  const events = Array.isArray(manifest?.events) ? manifest.events : null;
  const candidates = Array.isArray(config?.candidates) ? config.candidates : null;
  if (!events || events.length === 0) {
    throw new Error('Manifest must contain a non-empty "events" array');
  }
  if (!candidates || candidates.length === 0) {
    throw new Error('Config must contain a non-empty "candidates" array');
  }

  console.log(`Loading ${args.wavs.length} wav file(s)...`);
  const takes = [];
  for (const wavPath of args.wavs) {
    const decoded = await decodeWavMono(wavPath);
    takes.push({ file: wavPath, ...decoded });
    console.log(`  ${path.basename(wavPath)} -> ${decoded.sampleRate} Hz, ${decoded.durationSeconds.toFixed(2)}s`);
  }

  const evalCfg = config.evaluation ?? {};
  const candidateResults = [];
  for (const candidate of candidates) {
    console.log(`Running candidate: ${candidate.label ?? candidate.id}`);
    let runtimeMsTotal = 0;
    let analyzedDurationTotal = 0;
    const fileBreakdown = [];
    const mergedFrames = [];
    const mergedEvents = [];
    const perTakeMetrics = [];
    let timelineOffset = 0;

    for (let takeIndex = 0; takeIndex < takes.length; takeIndex += 1) {
      const take = takes[takeIndex];
      const result = runDetector(take.samples, take.sampleRate, candidate);
      runtimeMsTotal += result.runtimeMs;
      analyzedDurationTotal += result.durationSeconds;
      fileBreakdown.push({
        file: take.file,
        input_sample_rate: take.sampleRate,
        analysis_sample_rate: result.analysisSampleRate,
        audio_duration_s: result.durationSeconds,
        runtime_ms: result.runtimeMs
      });

      for (const frame of result.frames) {
        mergedFrames.push({
          t_seconds: frame.t_seconds + timelineOffset,
          midi_estimate: frame.midi_estimate,
          confidence: frame.confidence
        });
      }
      const offsetEvents = events.map((event) => ({
        ...event,
        start_s: event.start_s + timelineOffset,
        end_s: event.end_s + timelineOffset
      }));
      const metrics = evaluateFrames(result.frames, events, evalCfg);
      perTakeMetrics.push({
        file: take.file,
        ...metrics,
        runtime_ms: result.runtimeMs,
        audio_duration_s: result.durationSeconds,
        cpu_ms_per_audio_s: result.runtimeMs / Math.max(1e-6, result.durationSeconds)
      });

      for (const event of offsetEvents) {
        // mergedEvents is evaluated once to get aggregate medians/stddev over all takes.
        // Keep note_order unchanged so note summaries are grouped across takes.
        mergedEvents.push(event);
      }
      timelineOffset += result.durationSeconds + 1;
    }

    mergedFrames.sort((a, b) => a.t_seconds - b.t_seconds);
    const mergedMetrics = evaluateFrames(mergedFrames, mergedEvents, evalCfg);
    const cpuMsPerAudioSecond = runtimeMsTotal / Math.max(1e-6, analyzedDurationTotal);
    const realtimeFactor = analyzedDurationTotal / Math.max(1e-6, runtimeMsTotal / 1000);

    candidateResults.push({
      id: candidate.id,
      label: candidate.label ?? candidate.id,
      algorithm: candidate.algorithm,
      params: candidate.params ?? {},
      runtime_ms_total: runtimeMsTotal,
      analyzed_duration_s_total: analyzedDurationTotal,
      cpu_ms_per_audio_s: cpuMsPerAudioSecond,
      realtime_factor: realtimeFactor,
      quality_score: mergedMetrics.quality_score,
      metrics: mergedMetrics,
      per_take: perTakeMetrics,
      file_breakdown: fileBreakdown
    });
  }

  const speedValues = candidateResults.map((entry) => entry.cpu_ms_per_audio_s);
  const minSpeed = Math.min(...speedValues);
  const maxSpeed = Math.max(...speedValues);
  const qualityWeight = Number.isFinite(evalCfg.quality_weight) ? evalCfg.quality_weight : 0.8;
  const speedWeight = Number.isFinite(evalCfg.speed_weight) ? evalCfg.speed_weight : 0.2;

  const ranked = candidateResults.map((entry) => {
    const speedNorm = maxSpeed === minSpeed ? 1 : (maxSpeed - entry.cpu_ms_per_audio_s) / (maxSpeed - minSpeed);
    const combinedScore = qualityWeight * entry.quality_score + speedWeight * (speedNorm * 100);
    return {
      ...entry,
      speed_norm: speedNorm,
      combined_score: combinedScore
    };
  }).sort((a, b) => b.combined_score - a.combined_score);

  const output = {
    generated_at: new Date().toISOString(),
    manifest_path: args.manifest,
    wav_files: args.wavs,
    config_path: args.config,
    evaluation: {
      ...evalCfg,
      quality_weight: qualityWeight,
      speed_weight: speedWeight
    },
    ranking: ranked.map((entry, index) => ({
      rank: index + 1,
      id: entry.id,
      label: entry.label,
      combined_score: entry.combined_score,
      quality_score: entry.quality_score,
      speed_norm: entry.speed_norm,
      cpu_ms_per_audio_s: entry.cpu_ms_per_audio_s,
      realtime_factor: entry.realtime_factor
    })),
    candidates: ranked
  };

  await fs.mkdir(path.dirname(args.out), { recursive: true });
  await fs.writeFile(args.out, `${JSON.stringify(output, null, 2)}\n`, 'utf8');

  console.log('\nRanking (quality + speed):');
  for (const row of output.ranking) {
    console.log(
      `${row.rank}. ${row.label} | combined=${row.combined_score.toFixed(1)} | quality=${row.quality_score.toFixed(1)} | speed=${row.speed_norm.toFixed(2)} | cpu=${row.cpu_ms_per_audio_s.toFixed(1)}ms/audio-s | x${row.realtime_factor.toFixed(1)}`
    );
  }

  console.log('\nTop candidate detail:');
  const top = ranked[0];
  if (top) {
    const m = top.metrics;
    console.log(`  ${top.label}`);
    console.log(`  Detect rate: ${formatPercent(m.detect_rate)}`);
    console.log(`  In-tune rate: ${formatPercent(m.in_tune_rate)} (<= ${(evalCfg.in_tune_cents ?? 35)} cents)`);
    console.log(`  Median abs cents: ${formatMaybeNumber(m.median_abs_cents, 2)}`);
    console.log(`  Jitter cents: ${formatMaybeNumber(m.jitter_cents, 2)}`);
    console.log(`  Octave error rate: ${formatPercent(m.octave_error_rate)}`);
  }

  console.log(`\nOutput written to: ${args.out}`);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
